import './Mention.css'

export type MentionProps = {
  /** team — команда (лого) · player — игрок (герой / фото / буква), ссылка на страницу игрока */
  kind: 'team' | 'player'
  /** Как написано в тексте */
  label: string
  /** Лого команды / герой / фото игрока; нет — у команды просто плашка, у игрока буква */
  img?: string
  /** Картинка — фото игрока (лицо сверху), а не герой */
  photo?: boolean
  /** Буква без картинки (игрок) */
  letter?: string
  href?: string
}

const stop = (e: MouseEvent) => e.preventDefault()

/** Упоминание в тексте (лаба widget-news v65–v68, «плашкой»): команда — лого 13 + название, игрок — квадратик 11 (герой / фото) + ник; плашка на строке текста, на базовой линии. */
export function Mention({ kind, label, img, photo, letter, href = '#' }: MentionProps) {
  if (kind === 'team') return <span className={'mention mention--team' + (img ? '' : ' mention--nl')}>{img && <img src={img} alt="" />}{label}</span>
  return (
    <a className="mention mention--player" href={href} title="Страница игрока" onClick={stop}>
      <span className={'mention__av' + (photo ? ' mention__av--ph' : '')}>{img ? <img src={img} alt="" /> : <b>{letter ?? label[0]}</b>}</span>{label}
    </a>
  )
}
