/** Шахматка (круговая система; дирижёр 17.11, лаба tables-zones v9–v10): строки и колонки — одни и те же команды, в клетке — счёт строки против колонки.
 *  Собрана только из частей общей таблицы: HeadCell logo · Cell place (tone) / score / self / empty · Row tone · RowDivider. Лого везде 26. */
export type CrossLook = 'plate' | 'fill' | 'pill' | 'text'
/** out — снялась / заменена: строка приглушена, место «—», tag — плашка справа от имени */
export type CrossTeam = { id: string; sub?: string; out?: boolean; tag?: string }
/** Клетка: счёт; ff — тех (W / FF), re — переигровка (заметка) */
export type CrossScore = [number, number] | [number, number, { ff?: boolean; re?: string }]
export type CrossExtra = { key: string; label: string; width?: number; cell: (t: CrossTeam, i: number) => CellSpec }
export type CrossTableProps = {
  title: string
  /** Заголовок узлом вместо title (напр. переключатель стадии); title остаётся подписью таблицы для скринридера */
  head?: ReactNode
  sub?: string
  teams: CrossTeam[]
  /** Счёт команды строки против команды колонки; null — ещё не играли */
  score: (row: string, col: string) => CrossScore | null
  /** Итоговые колонки справа (серии, карты, ±) */
  extra?: CrossExtra[]
  /** Первые N — выходят: тон строк и разделитель с подписью */
  pass?: number
  /** Подпись разделителя зон */
  passLabel?: string
  narrow?: boolean
  /** Вид клетки и цвета (выбрано — plate · place · edge32: лаба rare-cases v4, дирижёр 18.11 — счёт плашкой, строки без цвета, место цветным квадратом); остальные — для лабы */
  look?: CrossLook
  toneLook?: 'bg' | 'place' | 'both' | 'off'
  zoneLook?: ZoneLook
}

export function CrossTable({ title, head, sub, teams, score, extra = [], pass, passLabel = '↑ Выход   ↓ Вылет', narrow: force, look = 'plate', toneLook = 'place', zoneLook = 'edge32' }: CrossTableProps) {
  const { ref, narrow } = useNarrow(640, force)
  const C = narrow ? 44 : 56
  const who = narrow ? 44 : 200
  const minW = 44 + who + teams.length * C + extra.reduce((s, e) => s + (e.width ?? 64), 0)
  const zone = pass != null && pass < teams.length
  const stdTone = toneLook === 'both', stdZone = zoneLook === 'edge32'
  const span = 2 + teams.length + extra.length
  const lab = zoneLook === 'label' || zoneLook === 'band-label' || zoneLook.startsWith('black') || zoneLook.startsWith('inset') || zoneLook.startsWith('edge')
  return (
    <div ref={ref} className={['dt3', 'xt', 'xt--' + look, zone && !stdTone && toneLook !== 'off' && 'dt3--tone-' + toneLook, zone && !stdZone && zoneLook !== 'none' && 'dt3--zone-' + zoneLook].filter(Boolean).join(' ')}>
      <Widget head="line" fluid title={head ?? title} sub={narrow ? undefined : sub}>
        <Table label={title} minWidth={minW} narrow={narrow} headH={32}>
          <colgroup><col style={{ width: 44 }} /><col style={{ width: who }} />{teams.map((t) => <col key={t.id} style={{ width: C }} />)}{extra.map((e) => <col key={e.key} style={{ width: e.width ?? 64 }} />)}</colgroup>
          <thead>
            <tr>
              <HeadCell>#</HeadCell><HeadCell align="left">{narrow ? '' : 'Команда'}</HeadCell>
              {teams.map((t) => <HeadCell key={t.id} logo={t.id} />)}
              {extra.map((e) => <HeadCell key={e.key}>{e.label}</HeadCell>)}
            </tr>
          </thead>
          <tbody>
            {teams.map((t, i) => {
              const tone = zone && toneLook !== 'off' ? (i < pass! ? 'up' as const : 'down' as const) : undefined
              return [
                <Row key={t.id} state={t.out ? 'muted' : undefined} tone={stdTone && !t.out ? tone : undefined} className={!stdTone && tone && !t.out ? 'row2--tone-' + tone : undefined}>
                  <Cell spec={t.out ? { main: { t: 'empty' }, align: 'center' } : { main: { t: 'place', n: i + 1 }, align: 'center' }} />
                  <Cell spec={narrow ? { start: { t: 'logo', team: t.id }, main: { t: 'empty' } } : { start: { t: 'logo', team: t.id }, main: { t: 'text', text: t.id, sub: t.sub, tag: t.tag } }} className={narrow ? 'xt__logo-only' : undefined} />
                  {teams.map((c) => {
                    if (c.id === t.id) return <Cell key={c.id} spec={{ main: { t: 'self', team: c.id } }} />
                    const s = score(t.id, c.id)
                    return <Cell key={c.id} spec={s ? { main: { t: 'score', a: s[0], b: s[1], ff: s[2]?.ff, re: s[2]?.re } } : { main: { t: 'empty' } }} />
                  })}
                  {extra.map((e) => <Cell key={e.key} spec={e.cell(t, i)} />)}
                </Row>,
                zone && i === pass! - 1 && (stdZone
                  ? <RowDivider key={t.id + ':zone'} span={span} label={passLabel} />
                  : zoneLook !== 'none' && <tr key={t.id + ':zone'} className="dt3-zone"><td colSpan={span}>{lab ? <span>{passLabel}</span> : null}</td></tr>),
              ]
            })}
          </tbody>
        </Table>
      </Widget>
    </div>
  )
}
