    const f = S && columns.find((c) => c.key === S.key)?.sort
    if (!f || !S) return rows
    return rows.map((r, i) => [r, i] as const).sort(([a, i], [b, j]) => {
      const x = f(a), y = f(b)
      return S.dir * (typeof x === 'string' || typeof y === 'string' ? String(x).localeCompare(String(y), 'ru') : (x as number) - (y as number)) || i - j
    }).map(([r]) => r)
