  const lead = columns.filter((c) => c.pin)
  const body = columns.filter((c) => !c.pin)
  const groups = [...new Set(body.map((c) => c.group ?? 'Главное'))]
  const [tab, setTab] = useState(groups[0])
  const expand = narrow && phone === 'expand'
  const mains = body.filter((c) => c.phoneMain)
  const main = mains.length ? mains : body.slice(0, 2)
  const det = body.filter((c) => !main.includes(c))
  const [open, setOpen] = useState<Set<string>>(new Set())
  useEffect(() => { if (openFirst && rows[0]) setOpen(new Set([rowKey(sorted[0] ?? rows[0])])) }, [openFirst]) // eslint-disable-line react-hooks/exhaustive-deps
  const toggle = (k: string) => setOpen((o) => { const n = new Set(o); n.has(k) ? n.delete(k) : n.add(k); return n })
  const cols = !narrow ? columns : expand ? [...lead, ...main] : [...lead, ...body.filter((c) => (c.group ?? 'Главное') === tab)]
  const span = cols.length + (expand ? 1 : 0)
  const grouped = !narrow && columns.some((c) => c.group)
  const left: Record<string, number> = {}
  if (!narrow) columns.filter((c) => c.pin).reduce((x, c) => ((left[c.key] = x), x + (c.width ?? 212)), 0)
  const minW = columns.reduce((s, c) => s + (c.width ?? (c.pin ? 212 : 56)), 0)
  const groupRow = cols.reduce<{ g?: string; n: number; k: string }[]>((a, c) => { const l = a[a.length - 1]; if (l && c.group && l.g === c.group) l.n++; else a.push({ g: c.group, n: 1, k: c.key }); return a }, [])

  // выбранный вид (дирижёр 17.11, tables-zones v9) — частями таблицы: Row tone + RowDivider; остальные виды — только для лабы
  const stdTone = toneLook === 'both'
  const stdZone = zoneLook === 'edge32'
  // черты зон — только в порядке по умолчанию и не после последней строки
  const inDefault = !sort || (S?.key === sort.key && S?.dir === sort.dir)
  const zoneAt = (i: number) => (zones && inDefault && i < list.length - 1 ? zones.find((z) => z.after === i + 1) : undefined)
