            <Row key={'sk' + i}>{cols.map((c) => <td key={c.key} className={'cell2' + (c.pin ? ' cell2--l' : '')}><Skeleton height={c.pin ? 14 : 10} width={c.pin ? '70%' : 28} /></td>)}{expand && <td />}</Row>
