/** Вкладки групп колонок на телефоне. Ширина — по тексту (не по самой узкой), в одну строку; места мало — прокрутка вбок,
 *  как папки в Telegram: нажатая вкладка сама едет к центру, так кликами доходишь до крайней. Места хватает — вкладки растягиваются поровну. */
function GroupTabs({ look, groups, value, onChange }: { look: TabsLook; groups: string[]; value: string; onChange: (g: string) => void }) {
  const box = useRef<HTMLDivElement>(null)
  useEffect(() => {
    const b = box.current, el = b?.querySelector<HTMLElement>('[aria-selected="true"]')
    if (b && el && b.scrollWidth > b.clientWidth) b.scrollTo({ left: el.offsetLeft - (b.clientWidth - el.offsetWidth) / 2, behavior: 'smooth' })
  }, [value])
  return (
    <div ref={box} className={'dt4-tabs dt4-tabs--' + look}>
      {/* eq: сетка шириной по содержимому, колонки 1fr — все вкладки шириной с самую длинную подпись (без замеров в JS); влезает — растягивается на всю ширину */}
      <div role="tablist" className="dt4-tabs__row">
        {groups.map((g) => <button key={g} type="button" role="tab" aria-selected={g === value} className={'dt4-tabs__b' + (g === value ? ' is-on' : '')} onClick={() => onChange(g)}>{g}</button>)}
      </div>
    </div>
  )
}

