import { DataTable, useNarrow, type Column, type DataTableProps, type SortState, type TabsLook } from './DataTable'
import './demo.css'

export type TableWidgetProps<T> = {
  title: string
  /** Заголовок узлом вместо title (напр. переключатель стадии «Групповой этап / Плей-офф» — лаба rare-cases v4); title остаётся подписью таблицы */
  head?: ReactNode
  /** Подпись серым после заголовка (на телефоне не показываем) */
  sub?: string
  rows: T[]
  columns: Column<T>[]
  rowKey: (r: T) => string
  /** Сортировка по умолчанию — к ней возвращает «Сбросить» */
  def: SortState
  /** Поля фильтра (2–3); нет — кнопки «Фильтр» нет */
  fields?: FilterField<T>[]
  /** Своё в шапке слева (сегмент стадии, выбор позиции) */
  actions?: ReactNode
  /** false — «Сбросить всё» не трогает сортировку и фильтр (только колонки и строки) */
  reset?: boolean
  /** На телефоне actions — отдельной строкой под шапкой, заголовок не жмётся (список турниров движка, лаба v39) */
  actionsBelow?: boolean
  narrow?: boolean
  tabsLook?: TabsLook
  phone?: 'tabs' | 'expand'
  status?: 'ready' | 'loading' | 'error'
  onRetry?: () => void
  /** Для историй: начальное значение фильтра */
  initial?: FilterValue
  className?: string
  /** Зоны таблицы (тон строк, черты) — пробрасываются в DataTable */
  zones?: Pick<DataTableProps<T>, 'rowTone' | 'rowState' | 'toneLook' | 'zones' | 'zoneLook'>
  /** Нажатие на строку */
  onRowClick?: (r: T) => void
  /** Пусто после фильтра — подпись (по умолчанию «Никого не нашли») */
  emptyText?: string
  /** v5: сведения о таблице — в шестерёнке (было «i» в actions) */
  info?: InfoTipData
  /** v5: false — без шестерёнки и «На весь экран» (маленькие таблицы) */
  tools?: boolean
  /** v5: строк сразу (по умолчанию 10; страницы-списки — 15, дирижёр 25.11); шаг «Показать ещё» — 10 */
  rows0?: number
}
const NONE: never[] = []

/** Виджет-таблица v5 (25.11, лаба tables-rules v22 — общие правила таблиц, TableTools): шапка «заголовок · [своё] [Фильтр] · шестерёнка · На весь экран»;
 *  «Сбросить» из шапки — в шестерёнке («Сбросить всё»: сортировка, фильтр, колонки, строки); 10 строк + «Показать ещё»; на весь экран — окном, ≥ 50 строк.
 *  Было v4: шапка «заголовок · подпись · [своё] [↺ Сбросить] [Фильтр]» + DataTable v4.
 *  Так собирается любая таблица страницы: колонки — ячейками из слотов, остальное — здесь. */
export function TableWidget<T>({ title, head, sub, rows, columns, rowKey, def, fields, actions, narrow: force, tabsLook, phone, status = 'ready', onRetry, initial, className, zones, onRowClick, emptyText, reset = true, actionsBelow, info, tools = true, rows0 }: TableWidgetProps<T>) {
  const f = useTableFilter((fields ?? NONE) as FilterField<T>[], rows, { value: initial })
  const { ref, narrow } = useNarrow(640, force)
  const [sort, setSort] = useState<SortState | null>(def)
  const isDef = sort?.key === def.key && sort.dir === def.dir && !f.count
  const t = useTableTools(f.rows.length, rows0)
  // скрыть можно всё, кроме закреплённых (место, имя) и колонок только для телефона
  const opts = columns.filter((c) => !c.pin && !c.phoneOnly).map((c) => ({ key: c.key, label: c.label, group: c.group }))
  const limit = narrow || status !== 'ready' ? undefined : t.more.limit
  return (
    <FullFrame full={t.full} onClose={() => t.setFull(false)}>
    <div ref={ref} className={[className, limit !== undefined && t.more.cut && 'tt-cut'].filter(Boolean).join(' ') || undefined}>
      <Widget head="line" fluid title={head ?? title} sub={narrow ? undefined : sub} actions={<>
        {!(actionsBelow && narrow) && actions}
        {fields && <TableFilter f={f} narrow={narrow} />}
        {tools && <TableSettings info={info} columns={narrow ? [] : opts} hidden={t.hidden} onToggle={t.toggle}
          dirty={t.dirty || (reset && !isDef)} onResetAll={() => { if (reset) { setSort(def); f.reset() } t.reset() }} />}
        {tools && <FullButton full={t.full} onChange={t.setFull} />}
      </>}>
        {actionsBelow && narrow && actions && <div className="dt4-ctl">{actions}</div>}
        <DataTable label={title} rows={f.rows} total={f.total} rowKey={rowKey} columns={columns} narrow={force} sort={def} sortValue={sort} {...zones} onSortChange={setSort}
          tabsLook={tabsLook} phone={phone} openFirst={phone === 'expand'} status={status} onRetry={onRetry} onRowClick={onRowClick} empty={emptyText}
          hidden={narrow ? undefined : t.hidden} limit={limit} />
        {limit !== undefined && <ShowMore total={f.rows.length} limit={limit} full={t.full} first={t.more.first} onChange={t.more.setOpen} />}
      </Widget>
    </div>
    </FullFrame>
  )
}
