export type SiteSection = 'matches' | 'tournaments' | 'fantasy' | 'news'
export const SITE_SECTIONS: { value: SiteSection; label: string }[] = [
  { value: 'matches', label: 'Матчи' },
  { value: 'tournaments', label: 'Турниры' },
  { value: 'fantasy', label: 'Фэнтези' },
  { value: 'news', label: 'Новости' },
]

export type SiteHeaderProps = {
  /** Раздел, где стоит страница: матч — «Матчи», турнир — «Турниры», новости — «Новости» */
  active: SiteSection
  /** Вошёл — кошелёк и аватар; гость — «Войти» */
  viewer?: Viewer
  /** Кошелёк вошедшего; по умолчанию — заглушка лабы */
  wallet?: Partial<WalletProps>
  /** Картинка аватара (путь в базе лабы) */
  avatar?: string
  onNavigate?: (s: SiteSection) => void
  onHome?: () => void
  onSearch?: () => void
  onLogin?: () => void
  onProfile?: () => void
}

/** Шапка сайта: лого, разделы, поиск, кошелёк баллов и профиль (у гостя — «Войти»). Одна на матче, турнире и новостях. */
export function SiteHeader({ active, viewer = 'in', wallet, avatar = ME.avatar, onNavigate, onHome, onSearch, onLogin, onProfile }: SiteHeaderProps) {
  const go = (fn?: () => void) => (e: React.MouseEvent) => { e.preventDefault(); fn?.() }
  return (
    <header className="site-header">
      <a className="site-header__brand" href="#" onClick={go(onHome)}><span className="site-header__logo">◆</span>GoatScout</a>
      <nav className="site-header__nav" aria-label="Разделы">
        {SITE_SECTIONS.map((s) => (
          <a key={s.value} href="#" aria-current={s.value === active ? 'page' : undefined} onClick={go(() => onNavigate?.(s.value))}>{s.label}</a>
        ))}
      </nav>
      <SearchField className="site-header__search" onClick={onSearch} />
      {viewer === 'guest' ? (
        <span className="site-header__me site-header__me--guest"><Button variant="outline" size="sm" className="site-header__login" onClick={onLogin}>Войти</Button></span>
      ) : (
        <span className="site-header__me">
          <Wallet balance={ME.balance} reserved={ME.reserved} predictions={myPredictions()} {...wallet} />
          <button className="site-header__prof" aria-label="Профиль" onClick={onProfile}><Avatar src={img(avatar)} /></button>
        </span>
      )}
    </header>
  )
}
