export type DataStatus = 'ok' | 'lag' | 'lost'
export type DataTimeProps = { status?: DataStatus }

const LOST_S = 120
const hms = (d: Date) => d.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit', second: '2-digit' })
