/** Раскладка по рядам: иконка встаёт в первый ряд, где до соседа слева не меньше gap % — иконки не налезают */
export const lanes = <T,>(l: T[], x: (v: T) => number, gap: number) => { const rows: number[] = []
  return [...l].sort((a, b) => x(a) - x(b)).map((v) => { const p = x(v); let r = rows.findIndex((last) => p - last >= gap); if (r < 0) { rows.push(p); r = rows.length - 1 } else rows[r] = p; return { v, p, r } }) }
