    <div className="sh3-menu">{[{ id: 'all' as const, name: 'Все игры' }, ...G].map((g) => <button key={g.id} type="button" className="sh3-menu__i" aria-current={g.id === game || undefined} onClick={() => setGame(g.id)}><span className="sp6-mi">{g.id === 'all' ? <Icon name="gamepad" size={16} /> : <GameIcon game={g.id} size={16} />}{g.name}</span>{g.id === game && <Icon name="check" size={16} />}</button>)}</div>
