const go = (href?: string) => { if (href) window.location.href = href }

/** Список турниров движка v6 — реальные турниры Dota 2 (Liquipedia) с цветными лого; календарь v9: год как HLTV, месяц плашками с лого. Две колонки, справа место под виджет. */
