    if (prev && dayOf(r) !== dayOf(prev)) { const empty = dayOf(r) - dayOf(prev) - 1; const g = 0.6 + Math.min(4, empty) * 0.5; if (empty > 0) gaps.push({ from: u, to: u + g, n: empty }); u += g }
    if (!prev || dayOf(r) !== dayOf(prev)) days.push({ label: r.date, from: u, to: u })
