export const Live: S = { args: { m: first((m) => m.state === 'live') } }
export const Скоро: S = { args: { m: first((m) => m.state === 'soon') } }
export const Напоминание: S = { name: 'Скоро · напомнить включено', args: { m: first((m) => m.state === 'soon'), reminded: true } }
export const Ждёт: S = { name: 'Ждёт соперника', args: { m: first((m) => m.state === 'tba') } }
export const Итог: S = { args: { m: first((m) => m.state === 'done') } }
