export type TeamMatchesProps = { t: TeamView; /** Адрес страницы матча; нет — строка без перехода */ matchHref?: (s: Series) => string | undefined }
/** Страница команды движка — ‼️ концепт (лаба team-page v36, дирижёр 23.11). «Последние матчи» — первым в правой колонке (лабы v32 + v36). Подпись — итог по сериям («5 побед · 2 поражения»).
 *  Строка = серия, всё по центру: полное название и лого команды · счёт по картам (дата мелко под ним) · лого и полное название соперника; проигрыш — счёт серым.
 *  Идущая — та же строка карточкой: Live и стадия, лого 32 с названиями, счёт крупно, время карты. Без рамок и полосок — подсветка наведением, у всех одинаковая. */
export function TeamMatches({ t, matchHref }: TeamMatchesProps) {
  return (
    <Widget head="card" fluid title="Последние матчи" icon="wd-history">
      <ul className="tm-ml">{t.series.map((s) => { const live = s.win === null
        return (
          <li key={s.id}><a className={'tm-m-c' + (live ? ' is-live' : '')} href={matchHref?.(s)}>
            {live && <span className="tm-ml__lh"><b className="tm-live"><i />Live</b><small>{s.stage}</small></span>}
            <span className="tm-m-c__m"><span className="tm-m-c__t"><span>{teamName(t.id)}</span><TeamLogo team={t.id} size={live ? 32 : 20} /></span>
              <span className="tm-m-c__s"><b className={'tm-m-sc' + (s.win === false ? ' is-l' : '')}>{s.score[0]}<i>:</i>{s.score[1]}</b>{!live && <small>{s.date}</small>}</span>
              <span className="tm-m-c__t is-r"><TeamLogo team={s.vs} size={live ? 32 : 20} /><span>{teamName(s.vs)}</span></span></span>
            {live && <small className="tm-ml__lt">{s.live}</small>}</a></li>) })}</ul>
    </Widget>)
}
