const Rk = ({ n }: { n: number }) => <em className={'tm-rk' + (n <= 3 ? ' is-top' : '')}>#{n}</em>
export type TeamTotalsProps = { t: TeamView }
/** Страница команды движка — ‼️ концепт (лаба team-page v36, дирижёр 23.11). «На TI 2026» — плитки (серии, винрейт карт, карты, пул героев, ср. карта); у первых трёх — место среди 16 команд, топ-3 — золотом. */
