export type SeriesMap = { win: boolean | null; dur: number }
export type Series = { id: string; t: number; date: string; vs: string; score: [number, number]; win: boolean | null; live?: string; stage: string; bo: number; maps: SeriesMap[] }
export type Member = { id: string; nick: string; name?: string; pos: number | 'coach'; photo?: string; country?: string; maps?: number; wins?: number; kda?: number; gpm?: number; xpm?: number; lh?: number; k?: number; d?: number; a?: number; heroes: string[]; pool?: { hero: string; maps: number; wins: number }[] }
export type HeroUse = { hero: string; n: number }
