    form: done.slice(0, 5).map((s) => s.win),
    roster,
    picks: ts.picks.map(([hero, n]) => ({ hero, n })),
    bans: ts.bans.map(([hero, n]) => ({ hero, n })),
    now: series.find((s) => s.live),
    heroAgg: [...agg.values()].sort((a, b) => b.maps - a.maps || b.wins - a.wins), pool: agg.size,
    avgDur: allMaps.length ? Math.round(allMaps.reduce((a, m) => a + m.dur, 0) / allMaps.length) : 0,
