export const Ссылки: S = { name: 'Карточка — ссылка на матч', args: { tour: 'ti', matchHref: (m) => '#match-' + m.letter } }
export const Снялась: S = { name: 'TI 2026 · команда снялась (тех. победа)', args: { tour: 'ti', cases: DEMO_CASES.tiPlayoffOut } }
