import { DB } from '@/data/db'
import { TOUR_ID, type TourKey } from '@/tournament/state'
import { tourCases, type TourCases } from '@/tournament/data/tour'
import { teamName } from '@/data/format'

/* eslint-disable @typescript-eslint/no-explicit-any */
/** from — буква матча, из которого команда упала в нижнюю сетку (как у start.gg) */
export type Side = { team?: string; label?: string; score?: number; win?: boolean; from?: string; /** снялась — плашка «Снялась» */ out?: boolean }
/** ff — тех. победа (W / FF): у победителя «тех» вместо счёта, у снявшейся — «Снялась», в шапке — «тех. победа» без Bo (лаба rare-cases v4) */
export type BMatch = { id: string; letter: string; ff?: boolean; a: Side; b: Side; state: 'done' | 'live' | 'soon' | 'tbd'; when?: string; bo?: number }
export type Round = { id: string; name: string; matches: BMatch[] }
export type BracketData = { upper: Round[]; lower: Round[]; final: Round }

type Feed = [string, 'w' | 'l']
type Slot = { id: string; feeds: [Feed, Feed] | null }
const R = (id: string, name: string, stage: string, slots: Slot[]) => ({ id, name, stage, slots })
const S = (id: string, a?: Feed, b?: Feed): Slot => ({ id, feeds: a && b ? [a, b] : null })
/** Схема 8 команд double elimination: какие матчи и откуда в них приходят */
const SCHEME = {
  upper: [
    R('uq', 'Четвертьфинал', 'Четвертьфинал верхней сетки', [S('uq1'), S('uq2'), S('uq3'), S('uq4')]),
    R('us', 'Полуфинал', 'Полуфинал верхней сетки', [S('us1', ['uq1', 'w'], ['uq2', 'w']), S('us2', ['uq3', 'w'], ['uq4', 'w'])]),
    R('uf', 'Финал', 'Финал верхней сетки', [S('uf1', ['us1', 'w'], ['us2', 'w'])]),
  ],
  lower: [
    R('l1', '1-й раунд', '1-й раунд нижней сетки', [S('l11', ['uq1', 'l'], ['uq2', 'l']), S('l12', ['uq3', 'l'], ['uq4', 'l'])]),
    R('lq', 'Четвертьфинал', 'Четвертьфинал нижней сетки', [S('lq1', ['l11', 'w'], ['us2', 'l']), S('lq2', ['l12', 'w'], ['us1', 'l'])]),
    R('ls', 'Полуфинал', 'Полуфинал нижней сетки', [S('ls1', ['lq1', 'w'], ['lq2', 'w'])]),
    R('lf', 'Финал', 'Финал нижней сетки', [S('lf1', ['ls1', 'w'], ['uf1', 'l'])]),
  ],
  final: R('gf', 'Гранд-финал', 'Гранд-финал', [S('gf1', ['uf1', 'w'], ['lf1', 'w'])]),
}
/** Буквы матчей A–N — по порядку раундов (лаба bracket v9, как у start.gg) */
export const LETTER: Record<string, string> = { uq1: 'A', uq2: 'B', uq3: 'C', uq4: 'D', us1: 'E', us2: 'F', uf1: 'G', l11: 'H', l12: 'I', lq1: 'J', lq2: 'K', ls1: 'L', lf1: 'M', gf1: 'N' }
