import { tourArgTypes } from '@/tournament/storyArgs'
import { Roster } from './Roster'

const { tour } = tourArgTypes
/** «Участники» движка — без раскрытия, состав сразу в строке (лаба tour-roster v7, созвон 20.11: 87-26 … 89-28). Стоит на странице турнира v5. */
