    const act = rows.map((t) => ({ t, s: span(t) })).filter((x) => x.s).sort((a, b) => a.s![0].localeCompare(b.s![0]) || b.s![1].localeCompare(a.s![1]) || a.t.tier - b.t.tier)
    const ends: string[] = [], laneOf = new Map<string, number>()
