  Graph?: typeof MapGraph
  Teams?: typeof MapTeams
  /** Справа от графика — колонка (движок v4: лог событий, 53-39): получает карту, «сейчас» и момент, может поставить момент */
  Side?: (p: { map: MapData; now: number; moment: number | null; onMoment: (t: number | null) => void }) => ReactNode
  /** Пропсы графика сверху (движок v4: step — линия тиками) */
  graphProps?: Record<string, unknown>
