/** Поле графика на странице матча, компьютер 1440: 1016 × 585 (родитель — position: relative). */
const Поле = (St: () => React.ReactNode) => <div style={{ position: 'relative', width: 1016, height: 585, margin: 24, background: 'var(--w-bg)' }}><St /></div>
