  const rows = (rad: boolean) => { const gr = new Map<number | null, [MapDeath, number]>()
    f.ds.filter((d) => d.rad === rad).forEach((d) => { const c = gr.get(d.hero); gr.set(d.hero, c ? [c[0], c[1] + 1] : [d, 1]) }); return [...gr.values()] }
