  const diff = Math.abs(g.radiant - g.dire)
  const lead: Side | null = diff < 50 ? null : g.radiant > g.dire ? 'radiant' : 'dire'
  const sc = before ? { radiant: 0, dire: 0 } : scoreAt(map, t)
