/** Значки показателей (лаба w-preview-2/_ws2.js) — 16 × 16, линией. Огонь, флаг, кубок — из атома Icon; карта и часы — свои (у атома другая сетка, ≈) */
const OWN: Partial<Record<AboutRow['icon'], ReactNode>> = {
  map: <path d="M2.5 4l3.7-1.5 3.6 1.5 3.7-1.5v9.5l-3.7 1.5-3.6-1.5-3.7 1.5z M6.2 2.5v9.5 M9.8 4v9.5" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinejoin="round" />,
  clock: <><circle cx="8" cy="8" r="5.8" fill="none" stroke="currentColor" strokeWidth="1.3" /><path d="M8 4.8V8l2.2 1.4" fill="none" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" /></>,
}
const RowIcon = ({ name }: { name: AboutRow['icon'] }) => name === 'map' || name === 'clock' ? <svg viewBox="0 0 16 16" aria-hidden="true">{OWN[name]}</svg> : <Icon name={name} size={12} />

/** Полоса «первая команда · вторая»: ширина первой части, какая из частей ярче */
function Bar({ first, best, className }: { first: number; best: number; className: string }) {
  return <div className={className}><i className={best === 0 ? 'is-best' : ''} style={{ width: first + '%' }} /><i className={best === 1 ? 'is-best' : ''} /></div>
}

export type AboutProps = { data?: AboutData; /** особый случай: отмена — блок «Шансы» (лаба w-stats wstA) */ case?: MatchCase; chances?: ChancesData }

/** «Шансы» — вид блока при отмене матча (лаба w-stats/_wst.js, wstA--big): крупно шанс, показатели в 3 колонки — у лучшей команды значение и лого, «против» — у другой; итог плиткой */
function Chances({ data }: { data: ChancesData }) {
  const [A, B] = data.teams
  return (
    <section className="st-chances">
      <div className="st-chances__hd"><b>Шансы</b><small>{data.sub}</small></div>
      <div className="st-chances__big">
        <span className="st-chances__t"><TeamLogo team={A.team} size={24} />{A.name}</span>
        <b className={'num' + (data.bigBest === 0 ? ' on' : '')}>{data.big[0]}</b>
        <small>шанс</small>
        <b className={'num' + (data.bigBest === 1 ? ' on' : '')}>{data.big[1]}</b>
        <span className="st-chances__t st-chances__t--b">{B.name}<TeamLogo team={B.team} size={24} /></span>
      </div>
      <div className="st-chances__grid">
        {data.rows.map((r) => (
          <div key={r.label} className="st-chances__cell"><small>{r.label}</small><span><b className="num">{r.value}</b><TeamLogo team={r.team} size={16} /><i>{r.vs}</i></span></div>
        ))}
        <div className="st-chances__fcc">
          <div className="st-chances__fc">
            <span><b>{data.sum.title}</b><small>{data.sum.text}<span className="st-chances__x">{data.sum.note}</span></small></span>
            <TeamLogo team={data.sum.team} size={40} />
          </div>
        </div>
      </div>
    </section>
  )
}

/** «О матче» — шансы команд до начала: крупно среднее 5 показателей, ниже показатели плитками и итог (лаба w-preview-2 + w-stats, вкладка «Статистика» до матча). */
export function About({ data = STATS_ABOUT, case: c = 'none', chances = STATS_CHANCES }: AboutProps) {
  if (c === 'cancel') return <Chances data={chances} />
  const [A, B] = data.teams
  return (
    <section className="st-about">
      <div className="st-about__hd"><b>О матче</b><small>{data.sub}</small></div>
      <div className="st-about__top">
        <span className="st-about__team"><TeamLogo team={A.team} size={36} /><b>{A.name}</b></span>
        <span className="st-about__big">
          <em className={'num' + (data.bigBest === 0 ? ' is-best' : '')}>{data.big[0]}</em>
          <small>{data.bigNote}</small>
          <em className={'num' + (data.bigBest === 1 ? ' is-best' : '')}>{data.big[1]}</em>
        </span>
        <span className="st-about__team st-about__team--b"><b>{B.name}</b><TeamLogo team={B.team} size={36} /></span>
      </div>
      <Bar className="st-about__bar" first={data.bar} best={data.barBest} />
      <div className="st-about__grid">
        {data.rows.map((r) => (
          <div key={r.label} className="st-about__cell">
            <div className="st-about__label"><span className="st-about__ic"><RowIcon name={r.icon} /></span><small>{r.label}</small></div>
            <div className="st-about__vals">
              <span className={r.side === 'a' ? 'is-on' : ''}><b className="num">{r.a}</b></span>
              <em className="st-about__chip"><TeamLogo team={r.chip.team} size={20} /><b className="num">{r.chip.value}</b></em>
              <span className={r.side === 'b' ? 'is-on' : ''}><b className="num">{r.b}</b></span>
            </div>
            <Bar className="st-about__sbar" first={r.bar} best={r.barBest} />
          </div>
        ))}
        <div className="st-about__cell st-about__sum">
          <TeamLogo className="st-about__ghost" team={data.sum.team} size={112} />
          <small>{data.sum.note}</small>
          <b>{data.sum.title}</b>
          <span className="num">{data.sum.text}</span>
        </div>
      </div>
    </section>
  )
}
