/** Смерти из kills_log убийц (_wg2.js, deathsOf) */
const deathsOf = (m: GsMap): MapDeath[] => {
  const heroId = Object.fromEntries(Object.entries(GS().heroes).map(([id, h]) => [h.short, +id]))
  const by = Object.fromEntries(m.players.map((p) => [p.hero_id, p]))
  return m.players.flatMap((p) => p.kills_log.map((l) => {
    const v = by[heroId[l.key.replace('npc_dota_hero_', '')]]
    return { t: l.time, hero: v?.hero_id ?? null, steam: v?.account_id ?? null, rad: v ? v.isRadiant : !p.isRadiant, killerHero: p.hero_id, killerSteam: p.account_id }
  })).sort((a, b) => a.t - b.t)
}

/** Башни, бараки, Рошан (_wg2.js, objs) */
const LANE: Record<string, string> = { top: 'верх', mid: 'мид', bot: 'низ' }
/** npc_dota_goodguys_tower2_mid → «T2 мид», npc_dota_badguys_melee_rax_bot → «Казармы низ» */
const bldLabel = (key: string) => { const ln = LANE[(/_(top|mid|bot)/.exec(key) ?? [])[1] ?? ''] ?? ''
  const tw = /tower(\\d)/.exec(key); return (tw ? 'T' + tw[1] : /rax/.test(key) ? 'Казармы' : 'Здание') + (ln ? ' ' + ln : '') }
const objectivesOf = (m: GsMap): MapObjective[] => m.objectives
