import { Icon } from '@/atoms/Icon'
import { logoOf, nameOf, type Match } from '../../data/news'
import './Filters.css'

export type FilterTopic = { id: string; name: string; logo?: string; count: number }
export type FiltersProps = {
  /** Матчи дня — первыми чипами; выбранный — с × */
  matches: { m: Match; count: number }[]
  topics: FilterTopic[]
  /** Выбранный матч (id) */
  match?: string | null
  /** Выбранная тема (id) */
  topic?: string | null
  onAll?: () => void
  /** Нажали на матч: выбран — снять, нет — выбрать */
  onMatch?: (id: string) => void
  onClearMatch?: () => void
  onTopic?: (id: string) => void
}

/** × у выбранного матча: иконка close в рамке 12 — линии 6 px толщиной 1,6 px, как в лабе (сетка 10) */
const X = <Icon name="close" size={12} strokeWidth={32 / 15} />

/** Ряд чипов фильтра (лаба .n2-ch): «Все» · матчи дня · | · темы (турнир, команды, трансферы, мнения…). Выбор один. */
export function Filters({ matches, topics, match, topic, onAll, onMatch, onClearMatch, onTopic }: FiltersProps) {
  const team = (id: string) => <><img className="filters__tl" src={logoOf(id)} alt="" />{nameOf(id, 'mid')}</>
  return (
    <div className="filters">
      <Button variant="chip" size="sm" pressed={!(topic || match)} onClick={onAll}>Все</Button>
      {matches.map(({ m, count }) => { const on = match === m.id
        return (
          <Button key={m.id} variant="chip" size="sm" pressed={on} className="filters__mc" onClick={() => onMatch?.(m.id)}>
            {team(m.a)}<span className="filters__s">{m.state === 'live' ? <><i className="filters__lv" />{m.score?.[0]}:{m.score?.[1]}</> : m.start.slice(11, 16)}</span>{team(m.b)}
            <small>{count}</small>
            {on && <span className="filters__x" onClick={(e) => { e.stopPropagation(); onClearMatch?.() }}>{X}</span>}
          </Button>
        ) })}
      <i className="filters__sep" />
      {topics.map((t) => (
        <Button key={t.id} variant="chip" size="sm" pressed={topic === t.id} onClick={() => onTopic?.(t.id)}>
          {t.logo && <img className="filters__tl" src={t.logo} alt="" />}{t.name}<small>{t.count}</small>
        </Button>
      ))}
    </div>
  )
}
