      {status !== 'ready' ? <>
        <ListHead onArchive={onArchive} />
        <div className="tours__scroll" aria-busy={status === 'loading' || undefined}>
          {status === 'error' ? <StatusError grow fill onRetry={onRetry} /> : <div className="tours__bd"><Skeleton width={36} height={12} className="tours__lbl" />{Array.from({ length: 6 }, (_, i) => (
            <span key={i} className="tours__tr"><SkeletonLines n={2} h={11} gap={5} widths={[32, 36]} /><SkeletonLines className="tours__m" n={2} h={12} gap={6} widths={['70%', '45%']} /></span>
          ))}</div>}
        </div>
      </> : t ? <Tour key={t.id} t={t} onBack={() => setCur(null)} /> : <List all={all} onOpen={setCur} onArchive={onArchive} />}
