`,O8e=`/** Статистика героев турнира — из единой базы (DB.heroStats), поля как в лабе (_db/compat.js → TN_HEROES):
 *  p — пики, pw — победы на пике, rd / dr — [игр, побед, поражений] за Radiant / Dire, b — баны, pb — пик + бан. */
import { DB } from '@/data/db'
import { TOUR_ID, type TourKey } from '../state'

export type HeroStat = { n: string; k: string; p: number; pw: number; rd: [number, number, number]; dr: [number, number, number]; b: number; pb: number }
export type HeroStats = { games: number; sub: string; list: HeroStat[] }

/* eslint-disable @typescript-eslint/no-explicit-any */
export function heroStats(tour: TourKey): HeroStats {
  const db: any = DB(), HS = db.heroStats(TOUR_ID[tour])
  return { games: HS.games, sub: HS.sub, list: HS.list.map((h: any) => ({ n: db.data.heroes[h.hero]?.name || h.hero, k: h.hero, p: h.picks, pw: h.pickWins,
    rd: [h.radiant[0], h.radiant[1], h.radiant[0] - h.radiant[1]], dr: [h.dire[0], h.dire[1], h.dire[0] - h.dire[1]], b: h.bans, pb: h.picks + h.bans })) }
}
