/** Медаль Immortal по месту, как в игре: топ-10, топ-100, остальные (картинки — OpenDota, lab/_db/img/ranks) */
export const medalSrc = (place: number) => '_db/img/ranks/rank_icon_8' + (place <= 10 ? 'c' : place <= 100 ? 'b' : '') + '.png'

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9а-я]/g, '')
const BY = Object.fromEntries(Object.entries(VALVE_PLACE).map(([n, v]) => [norm(n), v]))
/** Место игрока по нику (ники в составах пишутся по-разному: «Ace ♠» / «Ace» — сверяем без знаков, затем по началу) */
export function valvePlace(nick: string): number | undefined {
  const k = norm(nick); if (!k) return undefined
  if (BY[k]) return BY[k]
  const hit = Object.keys(BY).find((x) => x.startsWith(k) || k.startsWith(x))
  return hit ? BY[hit] : undefined
}
