// устойчивое псевдослучайное от строки — как в лабе
export const hash = (s: string) => { let x = 7; for (const c of s) x = (x * 31 + c.charCodeAt(0)) >>> 0; return x }

/** Замена в составе: позиция, кто выходит, срок */
export type Swap = { pos: number; who: string; type: SwapType; why?: string }
export type SwapType = 'map' | 'series' | 'day' | 'tour'
export const SWAP_TYPES: [SwapType, string][] = [['map', 'Map'], ['series', 'Series'], ['day', 'Day'], ['tour', 'Tournament']]
export const ROLE: Record<number, string> = { 1: 'Pos 1 · Carry', 2: 'Pos 2 · Mid', 3: 'Pos 3 · Offlane', 4: 'Pos 4 · Soft support', 5: 'Pos 5 · Hard support' }
/** Заметка «рассказа ростера»: dr — драфты на турнире, auto — система, ed — редакция */
export type Note = ['dr' | 'auto' | 'ed', string]

/** Пары игроков, давно играющих вместе (лаба r10): ‼️ пример */
