const dd = (s: string) => s.slice(8, 10) + '.' + s.slice(5, 7)

// ——— шапка ———
export type KV = { k: string; v: string; tag?: boolean; note?: string }
export type TourHead = { name: string; logo?: string; sub: string; info: KV[] }

